/* The RVA Engine service worker (generated by build.py from src/site/sw.js).
   Precaches the app shell so the app opens offline. The cache name carries the build version, so every
   deploy installs a fresh cache; the page offers an "Update" button and the new worker takes over on tap.
   SN12: FILES lists {u: url, h: sha256[:12] of the file}. Each cache stores that list as a small manifest, and on
   install the new worker copies every file whose hash is unchanged out of the previous cache, so a deploy only
   re-downloads what changed (three.js and the images usually stay put). GitHub Pages ignores _headers, so the
   worker has to do this itself. */
const VERSION = '1.1.0-2a8315e8c2';
const CACHE = 'rva-engine-' + VERSION;
const FILES = [
 {
  "u": "./",
  "h": "108d96a45597"
 },
 {
  "u": "index.html",
  "h": "108d96a45597"
 },
 {
  "u": "app.html",
  "h": "a24d34c312f5"
 },
 {
  "u": "site.css",
  "h": "3eca6d1c78d2"
 },
 {
  "u": "vendor/three-0.149.0.min.js",
  "h": "8a5f7249903b"
 },
 {
  "u": "manifest.webmanifest",
  "h": "1ef35ed49ef7"
 },
 {
  "u": "favicon.ico",
  "h": "446f20b533c8"
 },
 {
  "u": "icons/icon-192.png",
  "h": "f60efb73ffe2"
 },
 {
  "u": "icons/icon-512.png",
  "h": "c9010e9ca9b6"
 },
 {
  "u": "icons/maskable-192.png",
  "h": "bf9a9d51a411"
 },
 {
  "u": "icons/maskable-512.png",
  "h": "ee0732918b49"
 },
 {
  "u": "icons/apple-touch-icon.png",
  "h": "d2c3b3f1e360"
 },
 {
  "u": "img/skyline-night-800.webp",
  "h": "78a16f4f8d2a"
 },
 {
  "u": "img/skyline-night-1600.webp",
  "h": "630f2d9de823"
 },
 {
  "u": "img/playlist/wk-golden.jpg",
  "h": "ef8f4be7fd50"
 },
 {
  "u": "img/playlist/wk-home.jpg",
  "h": "6d9ab2abbab3"
 },
 {
  "u": "img/playlist/wk-lovely.jpg",
  "h": "1d34d1fd8a59"
 },
 {
  "u": "img/playlist/wk-recipe.jpg",
  "h": "7ed4f88f4a6b"
 },
 {
  "u": "img/playlist/wk-river.jpg",
  "h": "557e42e01a31"
 },
 {
  "u": "img/playlist/wk-september.jpg",
  "h": "e8c7793f2f4e"
 },
 {
  "u": "img/playlist/wk-sunday.jpg",
  "h": "8b39f2fc4859"
 }
];
const MANIFEST = '__rva-manifest.json';   // never requested by pages; lives only inside the caches
// Pages are refreshed in place by the network-first fetch handler, so a cached page may be newer than its manifest
// hash says. They are small: always fetch them fresh instead of carrying them over.
const isPage = u => u === './' || u.endsWith('.html');

async function carryOver() {
  // url -> cached Response from an older rva-engine-* cache whose manifest has the same hash
  const found = {};
  const names = (await caches.keys()).filter(k => k.startsWith('rva-engine-') && k !== CACHE);
  for (const name of names) {
    try {
      const old = await caches.open(name);
      const m = await old.match(MANIFEST);
      if (!m) continue;
      const hashes = await m.json();
      for (const f of FILES) {
        if (found[f.u] || isPage(f.u) || hashes[f.u] !== f.h) continue;
        const hit = await old.match(f.u);
        if (hit && hit.ok) found[f.u] = hit;
      }
    } catch (err) { /* unreadable old cache: just download */ }
  }
  return found;
}

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const found = await carryOver();
    await Promise.all(FILES.map(async f => {
      if (found[f.u]) {
        try { await cache.put(f.u, found[f.u]); return; } catch (err) { /* fall through to the network */ }
      }
      const res = await fetch(new Request(f.u, { cache: 'reload' }));
      if (!res.ok) throw new Error('precache ' + f.u + ' ' + res.status);
      await cache.put(f.u, res);
    }));
    // written last: a cache without a manifest is never used as a copy source
    const man = {};
    FILES.forEach(f => { man[f.u] = f.h; });
    await cache.put(MANIFEST, new Response(JSON.stringify(man), { headers: { 'content-type': 'application/json' } }));
  })());
  // first install takes over at once; updates wait for the page's "Update" tap (see SW_REG_JS in build.py)
  if (!self.registration.active) self.skipWaiting();
});

// install has already copied what it needs, so the old caches can go
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('rva-engine-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', e => { if (e.data === 'skipWaiting') self.skipWaiting(); });

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;            // CDN fallback and anything external: browser default
  if (url.pathname.endsWith('.exe')) return;            // big downloads are never cached
  if (req.mode === 'navigate') {
    // pages: network first so a fresh deploy shows up, cached copy when offline or slow (4 s)
    e.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(req, { ignoreSearch: true }) || await cache.match(url.pathname.endsWith('/') ? './' : 'app.html');
      try {
        const net = fetch(req);
        const res = cached ? await Promise.race([net, new Promise((_, no) => setTimeout(no, 4000))]) : await net;
        if (res && res.ok && FILES.some(f => url.pathname.endsWith(f.u.replace('./', '/')))) cache.put(req, res.clone());
        return res;
      } catch (err) {
        if (cached) return cached;
        throw err;
      }
    })());
    return;
  }
  // static assets: cache first (they are versioned with the cache), then network
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req)));
});
